function reliefCanvas(w=1000,h=800,mode=$('styleSelect').value){let c=document.createElement('canvas');c.width=w;c.height=h;let ctx=c.getContext('2d'),im=ctx.createImageData(w,h);for(let j=0;j<h;j++)for(let i=0;i<w;i++){let x=i/(w-1)*WIDTH,y=j/(h-1)*HEIGHT,z=elevationAt(field,x,y),dx=(elevationAt(field,x+.16,y)-elevationAt(field,x-.16,y))/320,dy=(elevationAt(field,x,y+.16)-elevationAt(field,x,y-.16))/320,shade=clamp((.99-dx*.27-dy*.30)/Math.sqrt(1+dx*dx*.2+dy*dy*.2),.65,1.20);let col=mode==='paper'?[237,235,214]:heightColor(z);if(mode==='exposure'&&doc.ecology){let eco=vegetationAt(doc,field,x,y),t=clamp((eco?.exposure||0)/1.35,0,1);col=[70+180*t,106+105*t,140-60*t];shade=1;}else if(mode==='height')shade=.94+shade*.065;else if(mode==='paper')shade=.9+shade*.1;let grain=(Math.sin(i*1.71+j*.73)*Math.sin(j*1.09-i*.27)+Math.sin(i*.067+j*.087))*.9;for(let k=0;k<3;k++)im.data[(j*w+i)*4+k]=clamp(col[k]*shade+grain,0,255);im.data[(j*w+i)*4+3]=255;}ctx.putImageData(im,0,0);return c;}
