  let offsets=[[0,base],[0,-(isPoint?55:70)],[-width*.5-28,0],[width*.5+28,0],[0,base+75],[-80,-75],[80,-75],[-90,base+65],[90,base+65]],best=null;
  for(let[dx,dy]of offsets){let rect={x:x+dx-width/2-7,y:y+dy-font-5,w:width+14,h:height+12},overlap=boxes.reduce((sum,b)=>sum+Math.max(0,Math.min(rect.x+rect.w,b.x+b.w)-Math.max(rect.x,b.x))*Math.max(0,Math.min(rect.y+rect.h,b.y+b.h)-Math.max(rect.y,b.y)),0),outside=Math.max(0,5-rect.x)+Math.max(0,rect.x+rect.w-1995)+Math.max(0,-rect.y)+Math.max(0,rect.y+rect.h-1595),score=overlap*100+outside*1000+Math.hypot(dx,dy-base);if(!best||score<best.score)best={x:x+dx,y:y+dy,font,small,gap,rect,score,leader:Math.abs(dx)>20||Math.abs(dy-base)>50};}
