 if(!f.hideLabel&&f.type!=='contour'&&!['ridge','trail','river'].includes(f.type)){let c=center(f),x=c[0]*100,y=c[1]*100,label=labelPositions.get(f.id);if(label.leader)el('path',{d:`M${x} ${y}L${label.x} ${label.y-label.font/2}`,stroke:'#6e7863','stroke-width':.75,'stroke-opacity':.45,fill:'none'},$('annotationLayer'));if(f.type==='peak'||f.type==='village'){let size=f.type==='peak'?25:30;el('use',{href:'#'+(f.placeKind==='lodge'?'lodge':f.type),x:x-size/2,y:y-size/2,width:size,height:size},$('annotationLayer'));text($('annotationLayer'),f.name,{x:label.x,y:label.y,'text-anchor':'middle',class:'map-label','font-size':label.font});text($('annotationLayer'),`${Math.round(Number(f.elevation)).toLocaleString()} m`,{x:label.x,y:label.y+label.gap,'text-anchor':'middle',class:'map-label','font-size':label.small,fill:'#7d7d63'});}else if(f.constraint==='saddle'){el('path',{d:`M${x-10} ${y-5}q10 17 20 0`,stroke:'#856b50','stroke-width':2,fill:'none'},$('annotationLayer'));text($('annotationLayer'),f.name,{x:label.x,y:label.y,'text-anchor':'middle',class:'map-label','font-size':label.font});text($('annotationLayer'),Math.round(Number(f.elevation)).toLocaleString()+' m',{x:label.x,y:label.y+label.gap,'text-anchor':'middle',class:'map-label','font-size':label.small});}else{text($('annotationLayer'),f.name,{x:label.x,y:label.y,'text-anchor':'middle',class:'map-label','font-size':label.font,'letter-spacing':f.type==='lake'?1:2});if(f.elevation)text($('annotationLayer'),f.type==='waterfall'?`${f.drop} m 落差`:`${Math.round(Number(f.elevation)).toLocaleString()} m`,{x:label.x,y:label.y+label.gap,'text-anchor':'middle',class:'map-label','font-size':label.small,fill:'#7b856a'});}}
 if(filter==='all'||groupTypes[filter]?.includes(f.type)){let hit;if(f.points.length===1){hit=el('circle',{cx:f.points[0][0]*100,cy:f.points[0][1]*100,r:18,fill:'transparent','pointer-events':'all'},$('hitLayer'));}else hit=el('path',{d:['river','trail'].includes(f.type)?smoothPath(f):d,class:'feature-hit'},$('hitLayer'));hit.dataset.id=f.id;hit.setAttribute('role','button');hit.setAttribute('aria-label',`${kinds[f.type]}：${f.name}`);hit.setAttribute('tabindex','-1');let title=el('title',{},hit);title.textContent=`${f.name} · ${kinds[f.type]}${f.elevation?' · '+f.elevation+' m':''}`;}
