 if(hasCurve(f)&&!f.locked){let i=clamp(pointIndex,0,f.points.length-1),a=f.points[i],handles=[];if(i)handles.push([i-1,1]);if(i<f.points.length-1)handles.push([i,0]);for(let[segment,handle]of handles){let p=f.curve.segments[segment][handle];el('path',{d:`M${a[0]*100} ${a[1]*100} L${p[0]*100} ${p[1]*100}`,class:'curve-guide'},g);let c=el('circle',{cx:p[0]*100,cy:p[1]*100,r:radius*.85,class:'curve-handle',role:'button','aria-label':`${handle?'入弯':'出弯'}方向手柄`},g);c.dataset.curveHandle=handle;c.dataset.curveSegment=segment;}}
