function renderSidebar(){let layers=$('layerList');layers.replaceChildren();for(let[id,name]of layerGroups){let row=document.createElement('div');row.className='layer-row'+(filter===id?' active':'');row.dataset.layer=id;let check=document.createElement('input');check.type='checkbox';check.checked=groupTypes[id].every(k=>visible[k]);check.setAttribute('aria-label','显示'+name);check.onchange=()=>{for(let k of groupTypes[id])visible[k]=check.checked;renderMap();renderVegetation();if(!check.checked&&groupTypes[id].includes(selectedFeature()?.type))select(null);};let b=document.createElement('button');b.type='button';b.setAttribute('aria-pressed',String(filter===id));let swatch=document.createElement('i');swatch.className='layer-swatch';swatch.style.setProperty('--swatch',colors[id]);let label=document.createElement('span');label.textContent=name;b.append(swatch,label);b.onclick=()=>{filter=filter===id?'all':id;for(let k of groupTypes[id])visible[k]=true;render();$('modeHint').textContent=filter==='all'?'选择一条等高线或范围线，拖动节点调整':`只选择${name} · 再次点击图层名称取消筛选`;};let count=document.createElement('span');count.className='count';count.textContent=doc.features.filter(f=>groupTypes[id].includes(f.type)).length;row.append(check,b,count);layers.append(row);}
 let list=$('placeList');list.replaceChildren();for(let f of doc.features.filter(f=>(['peak','lake','village','waterfall'].includes(f.type)||f.constraint==='saddle'))){let b=document.createElement('button');b.className=f.id===selected?'active':'';let icon=document.createElement('span');icon.className='place-icon';icon.textContent=f.constraint==='saddle'?'◇':f.type==='peak'?'△':f.type==='lake'?'≈':f.type==='waterfall'?'↡':'⌂';let label=document.createElement('span');label.textContent=f.name;let small=document.createElement('small');small.textContent=f.type==='waterfall'?f.drop+' m 落差':Math.round(Number(f.elevation)).toLocaleString()+' m';b.append(icon,label,small);b.onclick=()=>{visible[f.type]=true;filter='all';setTool('select');select(f.id);render();};list.append(b);}}
function renderInspector(){let f=selectedFeature();$('inspector').hidden=!f;if(!f)return;$('selectionKind').textContent=(f.locked?'已锁定 · ':'')+(f.placeKind==='lodge'?'山庄':f.constraint==='saddle'?'垭口':kinds[f.type]);$('featureName').value=f.name;$('featureElevation').value=f.elevation??4000;$('elevationLabel').hidden=!(f.constraint==='saddle'||['contour','peak','village','lake','forest','meadow','grassland','snow','waterfall'].includes(f.type));$('pointCount').textContent=`${f.points.length} 个${hasCurve(f)?'曲线点':'节点'}`;$('addPointButton').textContent=hasCurve(f)?'增加曲线点':'加密节点';$('pointControls').hidden=f.points.length===1;$('deletePointButton').disabled=f.points.length<=(f.closed?3:2)||f.locked;$('addPointButton').disabled=f.locked;$('lockButton').textContent=f.locked?'解锁':'锁定';$('deleteButton').disabled=f.locked;pointIndex=clamp(pointIndex,0,f.points.length-1);let p=f.points[pointIndex];$('pointX').value=p[0].toFixed(2);$('pointY').value=p[1].toFixed(2);for(let id of['pointX','pointY','featureElevation','featureName'])$(id).disabled=!!f.locked;$('inspectorHint').textContent=f.type==='waterfall'?`落差 ${f.drop} m · 瀑顶 ${Math.round(Number(f.elevation)).toLocaleString()} m → 瀑脚 ${Number(f.lowerElevation).toLocaleString()} m` :f.type==='trail'&&hasCurve(f)?(drag?.changed?'正在调整曲线，松开后检查坡度。':`${f.points.length} 个曲线点 · 选中圆点后拖方向手柄调弯度 · 最大纵坡约 ${(f.stats?.maxGrade*100||0).toFixed(1)}%${f.stats?.valid===false?' · 当前局部超出规划条件，请调整':''}`):f.type==='trail'&&f.stats?doc.hikingTrailsVersion?`登山步道 · ${f.stats.lengthKm.toFixed(2)} km · 规划最大纵坡 ${(f.stats.maxGrade*100).toFixed(1)}% · 等高线交角上限 45°／垭口段 60°`:`沿坡步道 · ${f.stats.lengthKm.toFixed(2)} km · 累计上升 ${Math.round(f.stats.ascentMetres)} m · 多数路段坡度约 ${Math.round(f.stats.p95Grade*100)}% 以下` :f.type==='river'&&field?(()=>{let p=riverProfile(field,f.points);return `按节点顺序流向下游 · ${Math.round(p.start).toLocaleString()} → ${Math.round(p.end).toLocaleString()} m · ${p.lengthKm.toFixed(2)} km${p.maxRise>.2?' · 当前河段存在逆坡，请调整节点':''}`;})():f.placeKind==='lodge'?'归云谷 · 藏月湖西岸。可移动位置、修改名称与注记高程。':f.constraint==='saddle'?'垭口高程参与地形计算，可调整鞍部的位置与高度。':f.terrainRole==='crest'?'山脊节点与地形联动，拖动节点后可配合等高线继续修整坡面。':f.type==='contour'?'等高线高程参与地形计算。拖动圆点调整坡面；请尽量避免不同高程的线相交。':f.type==='lake'?'湖岸和湖面高程共同参与地形计算；范围线内会整理为水平湖面。':['forest','meadow','grassland','snow'].includes(f.type)?'范围线控制该类景观的分布。这里的参考高程只作注记，地势由等高线控制。':'拖动圆点改变位置；也可以输入精确坐标。';}
function render(){$('curveModeButton').hidden=!doc.features.some(f=>f.type==='trail'&&!hasCurve(f));let title=doc.title||'雪隐山居 · 云岫山境';document.title=title+' · 地形工作台';$('draftName').textContent=title.replace(/^雪隐山居\s*·\s*/,'')+(doc.trailCurveVersion?' · 步道曲线编辑':doc.hikingTrailsVersion?' · 登山步道修订':doc.landscapeVersion?' · 山水生态修订':doc.riverRefinementVersion?' · 河谷修订':doc.gentleSatelliteVersion?' · 峰群草案 03 · 低峰微调':doc.peakClusterVersion?' · 峰群草案 03':doc.watershedShapeVersion?' · 山系草案 02':' · 草案 01');$('mapTitle').textContent=title.replace(/^雪隐山居\s*·\s*/,'');$('mapName').textContent=title;renderMap();renderSidebar();renderInspector();$('objectInfo').textContent=`${doc.features.filter(f=>f.type==='contour').length} 条等高线 · ${doc.features.filter(f=>f.type!=='contour').length} 个地形元素`;}
function select(id,node=0){selected=id;pointIndex=node;selectedTerrainPoint=selectedFeature()?.points[node]?[...selectedFeature().points[node]]:null;refreshTrailStats(selectedFeature());renderSelection();renderInspector();renderSidebar();}
function setTool(next){tool=next;svg.dataset.tool=tool;document.querySelectorAll('[data-tool]').forEach(b=>{b.classList.toggle('active',b.dataset.tool===next);b.setAttribute('aria-pressed',String(b.dataset.tool===next));});$('drawButton').classList.toggle('active',next==='draw');if(next!=='draw'){$('drawPanel').hidden=true;drawing=[];renderDrawing();}else{$('drawPanel').hidden=false;select(null);}$('modeHint').textContent=next==='pan'?'拖动平移 · 滚轮缩放':next==='draw'?'依次点击落点，按“完成绘制”保存图形':'拖动圆点调整形状 · 拖动线条整体移动';}
function screenPoint(e){let p=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());return[p.x/100,p.y/100];}
function updateView(){svg.setAttribute('viewBox',`${view.x} ${view.y} ${view.w} ${view.h}`);$('zoomLabel').textContent=Math.round(2180/view.w*100)+'%';renderSelection();}
function zoom(factor,cx=view.x+view.w/2,cy=view.y+view.h/2){let next=clamp(view.w*factor,300,4000),f=next/view.w;view.x=cx+(view.x-cx)*f;view.y=cy+(view.y-cy)*f;view.w=next;view.h*=f;updateView();}
function addNodeAt(f,p){if(hasCurve(f)){let near=nearestCurve(f,p);pointIndex=splitCurve(f,near.segment,near.t);return;}let distance=Infinity,index=0;for(let i=0;i<f.points.length-(f.closed?0:1);i++){let d=distanceSegment(p,f.points[i],f.points[(i+1)%f.points.length]);if(d<distance){distance=d;index=i;}}f.points.splice(index+1,0,[clamp(p[0],0,20),clamp(p[1],0,16)]);pointIndex=index+1;}
svg.addEventListener('pointerdown',e=>{if(e.button!==0&&e.button!==1)return;let p=screenPoint(e),handle=e.target.closest('[data-curve-handle]'),node=e.target.closest('[data-node]'),hit=e.target.closest('[data-id]');if(tool==='draw'&&!space){if(p[0]<0||p[0]>20||p[1]<0||p[1]>16)return;drawing.push(p);renderDrawing();if(['peak','village','label'].includes($('drawType').value))finishDrawing();return;}svg.setPointerCapture(e.pointerId);if(tool==='pan'||space||e.button===1){drag={kind:'pan',client:[e.clientX,e.clientY],view:{...view}};svg.dataset.dragging='true';return;}if(handle&&selected){let f=selectedFeature();if(f.locked)return;drag={kind:'handle',start:p,original:clone(f.points),originalCurve:clone(f.curve),segment:Number(handle.dataset.curveSegment),handle:Number(handle.dataset.curveHandle),changed:false};}else if(node&&selected){let f=selectedFeature();select(selected,Number(node.dataset.node));if(f.locked){toast('此图形已锁定，请先解锁。');return;}drag={kind:'node',start:p,original:clone(f.points),originalCurve:clone(f.curve||null),node:pointIndex,changed:false};}else if(hit){let f=doc.features.find(f=>f.id===hit.dataset.id);select(f.id);selectedTerrainPoint=affectsTerrain(f)?[...p]:null;if(f.locked){toast('此图形已锁定，请先解锁。');return;}drag={kind:'feature',start:p,original:clone(f.points),originalCurve:clone(f.curve||null),changed:false};}else{select(null);drag=null;}});
svg.addEventListener('pointermove',e=>{let p=screenPoint(e);if(p[0]>=0&&p[0]<=20&&p[1]>=0&&p[1]<=16)$('cursorInfo').textContent=`向东 ${p[0].toFixed(2)} km · 向南 ${p[1].toFixed(2)} km${field?' · '+Math.round(elevationAt(field,...p)).toLocaleString()+' m':''}`;if(!drag)return;if(drag.kind==='pan'){let m=svg.getScreenCTM(),dx=(e.clientX-drag.client[0])/m.a,dy=(e.clientY-drag.client[1])/m.d;view.x=drag.view.x-dx;view.y=drag.view.y-dy;updateView();return;}let f=selectedFeature();if(!f)return;let dx=p[0]-drag.start[0],dy=p[1]-drag.start[1];if(!drag.changed&&Math.hypot(dx,dy)>.012){remember();drag.changed=true;}if(!drag.changed)return;if(drag.originalCurve)f.curve=clone(drag.originalCurve);f.points=clone(drag.original);
 if(drag.kind==='handle'){let old=drag.originalCurve.segments[drag.segment][drag.handle];moveCurveHandle(f,drag.segment,drag.handle,[clamp(old[0]+dx,0,20),clamp(old[1]+dy,0,16)]);}
 else if(drag.kind==='node'){moveCurveKnot(f,drag.node,[clamp(drag.original[drag.node][0]+dx,0,20),clamp(drag.original[drag.node][1]+dy,0,16)]);selectedTerrainPoint=[...f.points[drag.node]];}
 else{let hull=[...drag.original,...(drag.originalCurve?.segments.flat()||[])];dx=clamp(dx,-Math.min(...hull.map(p=>p[0])),20-Math.max(...hull.map(p=>p[0])));dy=clamp(dy,-Math.min(...hull.map(p=>p[1])),16-Math.max(...hull.map(p=>p[1])));f.points=drag.original.map(p=>[p[0]+dx,p[1]+dy]);selectedTerrainPoint=affectsTerrain(f)?[drag.start[0]+dx,drag.start[1]+dy]:null;if(drag.originalCurve)f.curve.segments=drag.originalCurve.segments.map(s=>s.map(p=>[p[0]+dx,p[1]+dy]));}
 renderMap();renderInspector();});
function finishDrag(){let d=drag;drag=null;svg.dataset.dragging='false';if(d?.changed){renderVegetation();changed({terrain:affectsTerrain(selectedFeature())});}}
svg.addEventListener('pointerup',finishDrag);svg.addEventListener('pointercancel',finishDrag);svg.addEventListener('lostpointercapture',finishDrag);
svg.addEventListener('dblclick',e=>{if(tool==='draw'){return;}let f=selectedFeature();if(!f||f.locked||f.points.length===1||!e.target.closest('[data-id]'))return;remember();addNodeAt(f,screenPoint(e));changed({terrain:affectsTerrain(f)});toast('已在线条上增加节点');});
svg.addEventListener('wheel',e=>{e.preventDefault();let p=screenPoint(e);zoom(e.deltaY>0?1.12:1/1.12,p[0]*100,p[1]*100);},{passive:false});
function editSelected(fn,terrain=true){let f=selectedFeature();if(!f||f.locked)return;remember();fn(f);changed({terrain});}
function onCommit(id,fn){for(let event of ['change','blur'])$(id).addEventListener(event,fn);$(id).addEventListener('keydown',e=>{if(e.key==='Enter')$(id).blur();});}
onCommit('featureName',()=>{let f=selectedFeature(),name=$('featureName').value.trim()||kinds[f?.type];if(f&&name!==f.name)editSelected(f=>f.name=name,false);});
onCommit('featureElevation',()=>{let f=selectedFeature(),n=Number($('featureElevation').value);if(!f||n===f.elevation)return;if(!Number.isFinite(n)||n<0||n>9000){renderInspector();return;}editSelected(f=>f.elevation=n,affectsTerrain(f));});
for(let[id,i,max]of[['pointX',0,20],['pointY',1,16]])onCommit(id,()=>{let f=selectedFeature(),n=Number($(id).value);if(!f||!Number.isFinite(n)||Math.abs(n-f.points[pointIndex][i])<.00001)return;editSelected(f=>{let next=[...f.points[pointIndex]];next[i]=clamp(n,0,max);moveCurveKnot(f,pointIndex,next);selectedTerrainPoint=[...next];},affectsTerrain(f));renderVegetation();});
$('addPointButton').onclick=()=>{let f=selectedFeature();if(!f||f.locked||f.points.length===1)return;editSelected(f=>{if(hasCurve(f)){pointIndex=splitCurve(f,Math.min(pointIndex,f.points.length-2));return;}let a=f.points[pointIndex],j=(pointIndex+1)%f.points.length;if(!f.closed&&j===0)j=pointIndex-1;let b=f.points[j];let at=Math.max(pointIndex,j);f.points.splice(at,0,[(a[0]+b[0])/2,(a[1]+b[1])/2]);pointIndex=at;},affectsTerrain(f));};
$('deletePointButton').onclick=()=>{let f=selectedFeature();if(!f||f.points.length<=(f.closed?3:2))return;editSelected(f=>{removeCurveKnot(f,pointIndex);pointIndex=clamp(pointIndex-1,0,f.points.length-1);},affectsTerrain(f));};
$('deleteButton').onclick=()=>{let f=selectedFeature();if(!f||f.locked)return;remember();doc.features=doc.features.filter(x=>x.id!==f.id);selected=null;changed();renderVegetation();toast('图形已删除，可撤销恢复');};
$('lockButton').onclick=()=>{let f=selectedFeature();if(!f)return;remember();f.locked=!f.locked;changed({terrain:false});};
$('deselectButton').onclick=()=>select(null);
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));$('drawButton').onclick=()=>setTool(tool==='draw'?'select':'draw');$('cancelDraw').onclick=()=>setTool('select');
function renderDrawing(){let g=$('drawingLayer');g.replaceChildren();if(!drawing.length)return;el('path',{d:path({points:drawing,closed:false}),stroke:'#b99461','stroke-width':2,'stroke-dasharray':'5 4',fill:'none','vector-effect':'non-scaling-stroke'},g);for(let p of drawing)el('circle',{cx:p[0]*100,cy:p[1]*100,r:view.w/(svg.clientWidth||1000)*4,fill:'#b99461',stroke:'#fff8e9','stroke-width':1},g);$('finishDraw').textContent=`完成绘制${drawing.length?' ('+drawing.length+' 点)':''}`;}
function finishDrawing(){let type=$('drawType').value,closed=['forest','meadow','grassland','snow','lake'].includes(type)||(type==='contour'&&$('drawClosed').checked),point=['peak','village','label'].includes(type),min=point?1:closed?3:2;if(drawing.length<min){toast(`至少需要 ${min} 个节点。`);return;}let elevation=Number($('drawElevation').value);if(!Number.isFinite(elevation)||elevation<0||elevation>9000){toast('请输入 0–9,000 m 的设计高程。');return;}remember();let f={id:'user-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6),type,name:type==='contour'?elevation.toLocaleString()+' m 等高线':'新建'+kinds[type],closed,points:clone(point?drawing.slice(0,1):drawing)};if(['contour','lake','peak','village'].includes(type))f.elevation=elevation;if(type==='trail')autoCurve(f);doc.features.push(f);visible[type]=true;filter='all';setTool('select');selected=f.id;pointIndex=0;changed();renderVegetation();toast('新图形已添加，可继续调整节点');}
$('finishDraw').onclick=finishDrawing;
$('drawType').onchange=()=>{drawing=[];renderDrawing();let t=$('drawType').value;$('drawElevationLabel').hidden=!['contour','lake','peak','village'].includes(t);$('drawClosedLabel').hidden=t!=='contour';};
$('undoButton').onclick=()=>undo();$('redoButton').onclick=()=>undo(true);$('zoomIn').onclick=()=>zoom(.8);$('zoomOut').onclick=()=>zoom(1.25);$('fitButton').onclick=()=>{view={x:-90,y:-90,w:2180,h:1780};updateView();};
$('styleSelect').onchange=()=>{$('reliefImage').setAttribute('href',reliefCanvas().toDataURL('image/png'));renderVegetation();};
document.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||document.querySelector('dialog[open]'))return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);return;}if(e.code==='Space'){space=true;e.preventDefault();svg.style.cursor='grab';}if(e.key.toLowerCase()==='v')setTool('select');if(e.key.toLowerCase()==='h')setTool('pan');if(e.key==='Escape'){setTool('select');select(null);}if(e.key==='Enter'&&tool==='draw')finishDrawing();if((e.key==='Delete'||e.key==='Backspace')&&selected){e.preventDefault();if(selectedFeature()?.points.length===1)$('deleteButton').click();else $('deletePointButton').click();}});
document.addEventListener('keyup',e=>{if(e.code==='Space'){space=false;svg.style.cursor='';}});window.addEventListener('blur',()=>{space=false;finishDrag();});
for(let which of['layers','reference'])$(which+'Tab').onclick=()=>{for(let w of['layers','reference']){$(w+'Tab').setAttribute('aria-selected',String(w===which));$(w+'Panel').hidden=w!==which;}};
$('referenceOverlay').onchange=()=>$('sketchOverlay').setAttribute('display',$('referenceOverlay').checked?'inline':'none');$('referenceOpacity').oninput=()=>$('sketchOverlay').setAttribute('opacity',$('referenceOpacity').value/100);
$('helpButton').onclick=()=>$('helpDialog').showModal();$('exportButton').onclick=()=>$('exportDialog').showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
function download(blob,name){let a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('已导出 '+name);}
function downloadJSON(value,name){download(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),name);}
const stamp=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
$('downloadDesign').onclick=()=>{let out={...clone(doc),exportedAt:new Date().toISOString()};downloadJSON(out,`雪隐山居-地形设计-${stamp()}.json`);};
function exportWorld(){let heightfield=fieldFor(doc.features,401,321,500,doc.terrainBase);return{schema:'snowvalley-world-blueprint/1',sourceSchema:SCHEMA,title:doc.title,revision:doc.revision,units:'metres',bounds:{width:20000,depth:16000,origin:'north-west',threeTransform:'x = eastMeters - 10000; z = southMeters - 8000; y = elevationMeters'},heightfield:{columns:401,rows:321,spacingMeters:50,rowOrder:'north-to-south',columnOrder:'west-to-east',encoding:'absolute-elevation-metres',values:Array.from(heightfield.values,h=>Math.round(h*10)/10)},ecology:doc.ecology?{...doc.ecology,grid:{...doc.ecology.grid,spacingMetres:doc.ecology.grid.spacingKm*1000,spacingKm:undefined}}:null,trailNetwork:doc.trailNetwork?{...doc.trailNetwork,pointUnits:'metres',targets:doc.trailNetwork.targets.map(t=>({...t,point:t.point.map(v=>Math.round(v*1000))}))}:null,landscapeDesign:doc.landscapeDesign||null,features:doc.features.map(({baselinePoints,baselineElevation,...f})=>({...f,...(hasCurve(f)?{curve:{...f.curve,units:'metres',segments:f.curve.segments.map(s=>s.map(p=>p.map(v=>Math.round(v*100000)/100)))},sampledPoints:sampleCurve(f,.005).map(p=>p.map(v=>Math.round(v*100000)/100))}:{}),points:f.points.map(p=>p.map(v=>hasCurve(f)?Math.round(v*100000)/100:Math.round(v*1000))),...(f.holes?{holes:f.holes.map(h=>h.map(p=>p.map(v=>Math.round(v*1000))))}:{}),...(f.accessPoint?{accessPoint:f.accessPoint.map(v=>Math.round(v*1000))}:{}),...(f.hydrology?{hydrology:{...f.hydrology,...(f.hydrology.originalSource?{originalSource:f.hydrology.originalSource.map(v=>Math.round(v*1000))}:{}),...(f.hydrology.originalMouth?{originalMouth:f.hydrology.originalMouth.map(v=>Math.round(v*1000))}:{})}}:{})})),notes:doc.notes};}
function clusterBackup(action,value,key='before-peak-clusters'){return new Promise((resolve,reject)=>{let request=indexedDB.open('snowvalley-terrain-backups',1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('drafts'))request.result.createObjectStore('drafts');};request.onerror=()=>reject(request.error);request.onsuccess=()=>{let db=request.result,tx=db.transaction('drafts',action==='put'?'readwrite':'readonly'),store=tx.objectStore('drafts'),get=store.get(key),saved;get.onsuccess=()=>{saved=get.result;if(action==='put'&&!saved)store.put(value,key);};tx.oncomplete=()=>{db.close();resolve(saved);};tx.onerror=()=>{db.close();reject(tx.error);};};});}
$('downloadBeforeCurves').onclick=async()=>{try{let raw=await clusterBackup('get',null,'before-trail-curves');let data=raw?JSON.parse(raw):await(await fetch('./terrain-editor/before-trail-curves.json')).json();downloadJSON(data,'云岫山境-曲线编辑修订前.json');}catch{toast('备份暂时无法读取，当前草案已保留。');}};
