function exportSVG(){let copy=svg.cloneNode(true);copy.removeAttribute('tabindex');copy.setAttribute('xmlns',NS);copy.setAttribute('width',2400);copy.setAttribute('height',1920);copy.setAttribute('viewBox','-70 -90 2140 1760');for(let id of['selectionLayer','hitLayer','drawingLayer','sketchOverlay'])copy.querySelector('#'+id)?.remove();let style=el('style');style.textContent='.map-label{font-family:serif;paint-order:stroke;stroke:#f5f4e4;stroke-width:4px;stroke-linejoin:round;fill:#4d6250}.contour-label{font:19px sans-serif;fill:#8e896b;paint-order:stroke;stroke:#e5e6d2;stroke-width:3px}';copy.prepend(style);return new XMLSerializer().serializeToString(copy);}
$('downloadSVG').onclick=()=>download(new Blob([exportSVG()],{type:'image/svg+xml'}),`雪隐山居-地形地图-${stamp()}.svg`);
$('downloadPNG').onclick=async()=>{let source=new Blob([exportSVG()],{type:'image/svg+xml'}),url=URL.createObjectURL(source);try{let img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url;});let c=document.createElement('canvas');c.width=2400;c.height=1920;let ctx=c.getContext('2d');ctx.fillStyle='#eeeee4';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);let blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));download(blob,`雪隐山居-地形地图-${stamp()}.png`);}catch{toast('图片导出失败，请先导出 SVG 地图。');}finally{URL.revokeObjectURL(url);}};
$('downloadHeight').onclick=()=>{let f=fieldFor(doc.features,401,321,500,doc.terrainBase),header=new TextEncoder().encode('P5\n# Elevation 0..9000 m; north-west origin; spacing 50 m\n401 321\n65535\n'),bytes=new Uint8Array(header.length+f.values.length*2);bytes.set(header);for(let i=0;i<f.values.length;i++){let v=Math.round(clamp(f.values[i]/9000,0,1)*65535);bytes[header.length+i*2]=v>>8;bytes[header.length+i*2+1]=v&255;}download(new Blob([bytes],{type:'image/x-portable-graymap'}),`雪隐山居-高度图-0至9000m-${stamp()}.pgm`);};
$('importButton').onclick=()=>$('importFile').click();$('importFile').onchange=async()=>{let file=$('importFile').files[0];if(!file)return;try{if(file.size>20e6)throw Error('文件过大，请选择本编辑器导出的设计 JSON。');let parsed=validateDocument(JSON.parse(await file.text()));remember();doc=parsed;lastTerrainEditId=null;lastTerrainEditPoint=null;selected=null;pointIndex=0;changed();renderVegetation();toast('设计已导入，可继续编辑；也可以撤销返回。');}catch(err){toast(err instanceof SyntaxError?'文件不是有效的 JSON，当前地图已保留。':err.message);}finally{$('importFile').value='';}};
let previewOpening=0,previewFocus=null;
function previewFocusFeature(){let f=doc.features.find(f=>f.id===lastTerrainEditId)||selectedFeature();return f&&affectsTerrain(f)?{...f,focusPoint:f.id===lastTerrainEditId?lastTerrainEditPoint:selectedTerrainPoint||f.points[pointIndex]}:null;}
$('previewButton').onclick=async()=>{
 const opening=++previewOpening;let heightReady=false;$('previewDialog').showModal();$('previewButton').disabled=true;$('previewOverview').disabled=true;$('previewFocus').hidden=true;$('previewNote').textContent='正在同步当前等高线与地形…';
 try{
  const current=await terrainState.latest();heightReady=true;$('previewDialog').dataset.terrainRevision=String(doc.revision);$('previewDialog').dataset.terrainGeneration=String(terrainState.revision);
  let{TerrainPreview}=await import('./preview.js?v=7');
  if(opening!==previewOpening||!$('previewDialog').open)return;
  if(preview)preview.dispose();previewFocus=previewFocusFeature();
  preview=new TerrainPreview($('previewScene'),current,doc.features,Number($('verticalScale').value),doc.ecology,previewFocus);
  $('previewFocus').hidden=!previewFocus;$('previewOverview').disabled=false;preview.focusFeature(previewFocus);$('previewNote').textContent=previewFocus?'已同步当前等高线 · 已定位修改区域 · 拖动旋转、滚轮缩放':'已同步当前等高线 · 拖动旋转、滚轮缩放';
 }catch(e){console.error(e);$('previewNote').textContent=heightReady?'地形已按当前等高线更新；当前设备暂时无法打开三维画面。':'地形重算未完成，请关闭预览后重试；当前草案已保留。';}
 finally{if(opening===previewOpening)$('previewButton').disabled=false;}
};
$('previewFocus').onclick=()=>{preview?.focusFeature(previewFocus);$('previewNote').textContent=previewFocus?.type==='contour'?'已定位修改区域 · 金色线为当前等高线':'已定位修改区域';};
$('previewOverview').onclick=()=>{preview?.focusFeature(null);$('previewNote').textContent='已同步当前等高线 · 全图视角';};
$('verticalScale').onchange=()=>preview?.setScale(Number($('verticalScale').value),doc.ecology);
$('previewDialog').addEventListener('close',()=>{previewOpening++;$('previewButton').disabled=false;preview?.dispose();preview=null;});
async function newDraft(){try{let response=await fetch(new URL('./default-terrain.json?v=curves-1',import.meta.url));if(!response.ok)throw Error('default unavailable');return validateDocument(await response.json());}catch{let fresh=makeDocument(),heights={'main-peak':6840,'west-peak':6380,'sw-peak':6060,'south-peak':5740,'north-peak':6360,'east-peak':5680};for(let f of fresh.features)if(heights[f.id])f.elevation=heights[f.id];return fresh;}}
try{let stored=localStorage.getItem(STORE);if(stored){try{if(JSON.parse(stored).storage==='indexeddb')stored=await activeDraft();doc=validateDocument(JSON.parse(stored));$('saveState').textContent='已恢复此浏览器中的草案';}catch{doc=await newDraft();toast('旧草案无法读取，已载入初始设计。');}}else doc=await newDraft();}catch{doc=await newDraft();}
if(nameDraft(doc)){doc.revision=(Number(doc.revision)||1)+1;doc.updatedAt=new Date().toISOString();}
let watershedUpgrade=false;
if((doc.watershedShapeVersion||0)<2&&localStorage.getItem(STORE+'-watersheds-applied')!=='2'){
 try{if(!localStorage.getItem(STORE+'-before-watersheds'))localStorage.setItem(STORE+'-before-watersheds',JSON.stringify(doc));}catch(e){console.warn('山系重设计前备份未能保存',e);}
 remember();watershedUpgrade=redesignWatersheds(doc);if(watershedUpgrade)try{localStorage.setItem(STORE+'-watersheds-applied','2');}catch{}
}
let clusterUpgrade=false,clusterBackupSaved=true;
if((doc.peakClusterVersion||0)<2&&localStorage.getItem(STORE+'-clusters-applied')!=='2'){
 try{await clusterBackup('put',JSON.stringify(doc));}catch{clusterBackupSaved=false;}
 remember();if(doc.peakClusterVersion===1){let original=await clusterBackup('get');if(original)doc=validateDocument(JSON.parse(original));}clusterUpgrade=redesignPeakClusters(doc);if(clusterUpgrade)try{localStorage.setItem(STORE+'-clusters-applied','2');}catch{}
}
let restored03=false,gentleUpgrade=false,gentleBackupSaved=true;
if(doc.compactMassifVersion&&!doc.gentleSatelliteVersion){
 await clusterBackup('put',JSON.stringify(doc),'rejected-compact-04').catch(()=>{});
 let previous=await clusterBackup('get',null,'before-compact-massif').catch(()=>null);
 remember();
 if(previous)doc=validateDocument(JSON.parse(previous));
 else{let response=await fetch(new URL('./cluster-03-baseline.json',import.meta.url));if(!response.ok)throw Error('峰群草案03暂时无法读取，请稍后刷新。');doc=validateDocument(await response.json());}
 restored03=true;
}
if((doc.gentleSatelliteVersion||0)<2&&localStorage.getItem(STORE+'-gentle-applied')!=='2'){
 try{await clusterBackup('put',JSON.stringify(doc),'before-gentle-satellites');}catch{gentleBackupSaved=false;}
 remember();if(doc.gentleSatelliteVersion===1){let original=await clusterBackup('get',null,'before-gentle-satellites');if(original)doc=validateDocument(JSON.parse(original));}gentleUpgrade=gentlyMoveSatellites(doc);if(gentleUpgrade)try{localStorage.setItem(STORE+'-gentle-applied','2');}catch{}
}
let riversUpgrade=false,riverUpgradeError=false;
if((doc.riverRefinementVersion||0)<2&&localStorage.getItem(STORE+'-rivers-applied')!=='2'){
 try{await clusterBackup('put',JSON.stringify(doc),'before-rivers');let next=clone(doc);if(next.riverRefinementVersion===1){let original=await clusterBackup('get',null,'before-rivers');if(original)next=validateDocument(JSON.parse(original));}riversUpgrade=refineRivers(next);if(riversUpgrade){remember();doc=next;try{localStorage.setItem(STORE+'-rivers-applied','2');}catch{}}}catch{riverUpgradeError=true;}
}
let curveUpgrade=false;
async function enableCurveEditing(){let original=clone(doc),next=clone(doc),reference=null;if(next.features.some(f=>f.type==='trail'&&!hasCurve(f)))delete next.trailCurveVersion;try{let r=await fetch('./terrain-editor/before-trail-curves.json');if(r.ok)reference=await r.json();}catch{}let currentField=fieldFor(next.features,401,321,500,next.terrainBase);let result=convertTrailCurves(next,currentField,{reference});if(!result)return false;await clusterBackup('put',JSON.stringify(original),'before-trail-curves');remember();doc=next;field=currentField;trailAuditContext=null;localStorage.setItem(STORE+'-trail-curves-applied','1');return true;}
$('curveModeButton').onclick=async()=>{try{let result=await enableCurveEditing();if(result){selected=null;render();persist();toast('已恢复曲线编辑：拖动圆点和方向手柄调整步道；原稿已备份。');}}catch{toast('部分步道暂未通过曲线检查，原稿已保留。');}};
if(doc.trailCurveVersion)try{localStorage.setItem(STORE+'-trail-curves-applied','1');}catch{}
else if(doc.hikingTrailsVersion&&localStorage.getItem(STORE+'-trail-curves-applied')!=='1'){try{curveUpgrade=await enableCurveEditing();}catch{toast('步道曲线暂未自动转换，原稿已保留；可点击“恢复曲线编辑”重试。');}}
renderFrame();field=doc.riverRefinementVersion?fieldFor(doc.features,401,321,500,doc.terrainBase):fieldFor(doc.features,201,161,300,doc.terrainBase);render();renderVegetation();updateHistory();setTool('select');await rebuildTerrain();persist();if(curveUpgrade)toast('步道已恢复为少量控制点的曲线，原稿已备份。');else if(riverUpgradeError)toast('河流暂时无法自动整理，原草案已保留，可继续编辑。');else if(riversUpgrade)toast('河流已沿下坡谷地重新整理，栖月山庄已建于藏月湖西侧；原稿已备份。');else if(gentleUpgrade)toast(gentleBackupSaved?'峰群草案03已恢复：仅小幅内移八座低峰，原版已备份。':'低峰微调已完成；备份未能保存，本次可撤销返回。');else if(restored03)toast('已恢复峰群草案03原始地貌。');else if(clusterUpgrade)toast('峰群草案03已载入。');
